static int tests_run;
static int tests_passed;

#define TEST(name)                \
	do {                          \
		tests_run++;              \
		printf("  %-50s ", name); \
		fflush(stdout);           \
	} while (0)

#define PASS()            \
	do {                  \
		tests_passed++;   \
		printf("PASS\n"); \
	} while (0)

#define FAIL(msg)                  \
	do {                           \
		printf("FAIL: %s\n", msg); \
	} while (0)

typedef struct {
	unsigned int next_offset;
	unsigned int child_offset;
	unsigned int child_count;
	int skip_entry;
	sti2_entry_t entry;
} sit5_parsed_entry_t;

typedef struct {
	char path[STI2_PATH_LEN];
	char sha256[STUFFIT_SHA256_HEX_LEN + 1];
	unsigned int size;
	unsigned int method;
	unsigned int archive_data_offset;
	unsigned int archive_data_length;
	int has_method;
	int has_archive_data_offset;
	int has_archive_data_length;
	int is_dir;
	int is_resource;
} stuffit_manifest_entry_t;

typedef struct {
	char archive_name[STUFFIT_ARCHIVE_NAME_LEN];
	stuffit_manifest_entry_t entries[STUFFIT_MANIFEST_MAX_ENTRIES];
	int num_entries;
} stuffit_manifest_t;

typedef struct {
	uint32_t state[8];
	uint64_t bit_count;
	unsigned char buffer[64];
	unsigned int buffer_len;
} sha256_ctx_t;

static unsigned int be16(const unsigned char *p)
{
	return ((unsigned int) p[0] << 8) | (unsigned int) p[1];
}

static unsigned int be32(const unsigned char *p)
{
	return ((unsigned int) p[0] << 24) |
	       ((unsigned int) p[1] << 16) |
	       ((unsigned int) p[2] << 8) |
	       (unsigned int) p[3];
}

static int file_exists(const char *path)
{
	stat_t st;

	return stat_file(path, &st) == 0;
}

static int read_binary_file(const char *path, std::vector<unsigned char> *out_buf)
{
	FILE *f;
	long len;

	if (!out_buf)
		return -1;
	out_buf->clear();

	f = fopen(path, "rb");
	if (!f)
		return -1;
	fseek(f, 0, SEEK_END);
	len = ftell(f);
	fseek(f, 0, SEEK_SET);
	if (len < 0) {
		fclose(f);
		return -1;
	}
	out_buf->resize((size_t) len);
	if ((size_t) len != 0 && fread(out_buf->data(), 1, (size_t) len, f) != (size_t) len) {
		out_buf->clear();
		fclose(f);
		return -1;
	}
	fclose(f);
	return 0;
}

static void path_join(char *out, int out_len, const char *a, const char *b)
{
	snprintf(out, out_len, "%s/%s", a, b);
}

static void sanitize_name(const char *src, char *dst, int dst_len)
{
	int out_len = 0;

	while (*src && out_len < dst_len - 1) {
		char c = *src++;

		if ((c >= 'a' && c <= 'z') ||
		    (c >= 'A' && c <= 'Z') ||
		    (c >= '0' && c <= '9') ||
		    c == '.' || c == '_')
			dst[out_len++] = c;
		else
			dst[out_len++] = '_';
	}

	dst[out_len] = '\0';
}

static int copy_string_to_buffer(const std::string &value, char *out, size_t out_len)
{
	if (!out || out_len == 0 || value.size() >= out_len)
		return -1;
	memcpy(out, value.c_str(), value.size() + 1u);
	return 0;
}

static int json_to_uint(const json &value, unsigned int *out)
{
	std::uint64_t raw_value;

	if (!out || (!value.is_number_unsigned() && !value.is_number_integer()))
		return -1;
	if (value.is_number_unsigned()) {
		raw_value = value.get<std::uint64_t>();
	} else {
		std::int64_t signed_value = value.get<std::int64_t>();

		if (signed_value < 0)
			return -1;
		raw_value = (std::uint64_t) signed_value;
	}
	if (raw_value > std::numeric_limits<unsigned int>::max())
		return -1;
	*out = (unsigned int) raw_value;
	return 0;
}

static int json_extract_optional_uint_field(const json &object, const char *key,
                                            unsigned int *out, int *has_value)
{
	json::const_iterator it;

	if (!key || !out || !has_value)
		return -1;
	*has_value = 0;
	*out = 0;
	it = object.find(key);
	if (it == object.end() || it->is_null())
		return 0;
	if (json_to_uint(*it, out) < 0)
		return -1;
	*has_value = 1;
	return 0;
}

